.type) like (\'%grn%\')THEN \'WPR Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' and ( lower(a.\"Created By\") like \'%hemant%\' or lower(a.\"Created By\") like \'%adava%\' or lower(a.\"Created By\") like \'%guramm%\' or lower(a.\"Created By\") like \'%divya%\' ) THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%grn%\' THEN \'New Inward\' WHEN LOWER(a.type) LIKE \'%reverse%\' OR LOWER(a.type) LIKE \'%return%\' THEN \'B2C Return Inward\' WHEN LOWER(a.type) LIKE \'%cancelled%\' OR LOWER(a.type) LIKE \'%picklist%\' THEN \'Putback Activity\' WHEN LOWER(a.type) LIKE \'%shelf%\' THEN \'Audit Activity\' WHEN LOWER(a.type) LIKE \'%gatepass%\' THEN \'Gatepass Activity\' ELSE \'BAU_PT\' END AS final_type, a.type AS putaway_type, a.created::timestamp AS putaway_created, a.updated::timestamp AS putaway_updated, a.updated::date as putaway_completed_date, a.\"Inventory Type\", CAST(a.\"Total Quantity\" AS NUMERIC) AS total_quantity, CAST(a.\"Putaway Completed Quantity\" AS NUMERIC) AS putaway_completed_quantity, CAST(a.\"Total Quantity\" - a.\"Putaway Completed Quantity\" AS NUMERIC) AS pending_qty, a.\"Putaway Status Code\", upper(a.\"Putaway Item Status Code\") as \"Putaway Item Status Code\" , a.\"Bad inventory Reason\", a.\"Warehouse Name\", a.\"Putaway Item Id\", a.\"Item Type skuCode\", a.\"Putaway qc Comment\", a.\"Created By\", a.\"Shelf Code\", c.sku_group, c.\"SKU_CLASS\" AS class, a.Category, a.EAN, a.NAME AS product_name, a.\"Batch Code\" FROM snitch_db.maplemonk.snitch_final_get_put_away_new AS a LEFT JOIN snitch_db.maplemonk.uc_final_item_master AS c ON a.\"Item Type skuCode\" = c.sku WHERE a.updated::date >= \'2024-04-01\' ;",
